package dev.mcc.core;
import org.junit.jupiter.api.Test;
import java.util.*;
import static dev.mcc.core.AutomationGraphTest.*;
import static org.junit.jupiter.api.Assertions.*;
class AutomationCatalogTest {
 @Test void ExtendedCatalogHasTypedNativeOperationsWithoutPrivilegeCommands(){assertEquals(14,AutomationGraph.TRIGGERS.size());assertEquals(20,AutomationGraph.CONDITIONS.size());assertEquals(24,AutomationGraph.ACTIONS.size());for(String action:List.of("server.command","player.op","player.ban","server.restart","plugin.install"))assertThrows(IllegalArgumentException.class,()->AutomationGraph.validateAction(action,Map.of()));for(String trigger:AutomationGraph.TRIGGERS){var value=simple();nodes(value).getFirst().put("config",Map.of("trigger",trigger,"intervalSeconds",30));assertEquals(trigger,AutomationGraph.compile(value).trigger());}}
 @Test void BooleanConditionsRejectNumericComparisonsAndUnsafeCoordinates(){var value=graph(List.of(trigger(),node("check","condition",Map.of("condition","playerPermission","operator","gte","permission","minecraft.command.help","value",true)),action("set",1)),List.of(edge("a","start","check","next"),edge("b","check","set","true")));assertThrows(IllegalArgumentException.class,()->AutomationGraph.compile(value));nodes(value).get(1).put("config",Map.of("condition","playerDistance","operator","lte","value",10,"x",Double.NaN,"y",80,"z",0));assertThrows(IllegalArgumentException.class,()->AutomationGraph.compile(value));AutomationGraph.validateAction("event.start",Map.of("preset","treasure","loot",List.of(Map.of("material","DIAMOND","amount",4,"weight",2))));assertThrows(IllegalArgumentException.class,()->AutomationGraph.validateAction("event.start",Map.of("preset","waves","mob","WITHER")));}
 @Test void TriggerContextCannotSmuggleCommandArgumentsOrOversizedPayloads(){var context=AutomationGraph.context(Map.of("uuid",UUID.randomUUID().toString(),"world","world","material","DIAMOND_ORE","server.command","op someone","eventId",UUID.randomUUID().toString()));assertFalse(context.containsKey("server.command"));assertEquals("DIAMOND_ORE",context.get("material"));assertThrows(IllegalArgumentException.class,()->AutomationGraph.context(Map.of("material","x".repeat(151))));}
}
